def band_minutes(start: int, end: int) -> dict:
    if start > end:
        raise ValueError("start must be <= end")

    if end - start < 5:
        return {"day": 0, "night": 0, "weekend": 0}

    def count_bands(n: int):
        """Count (day, night, weekend) minutes in the range [0, n)."""
        if n <= 0:
            return (0, 0, 0)
        full_weeks = n // 10080
        remainder = n % 10080

        day_count = full_weeks * 4800
        night_count = full_weeks * 2400
        weekend_count = full_weeks * 2880

        # Count bands in the partial week (week-minutes 0 .. remainder-1)
        for d in range(7):
            day_start = d * 1440
            day_end = day_start + 1440
            a = max(0, day_start)
            b = min(remainder, day_end)
            if a >= b:
                continue
            tod_a = a - day_start
            tod_b = b - day_start

            if d >= 5:  # Saturday or Sunday
                weekend_count += tod_b - tod_a
            else:
                # Night: tod < 360 or tod >= 1320
                night_count += max(0, min(tod_b, 360) - tod_a)
                night_count += max(0, tod_b - max(tod_a, 1320))
                # Day: 360 <= tod < 1320
                day_count += max(0, min(tod_b, 1320) - max(tod_a, 360))

        return (day_count, night_count, weekend_count)

    d_end, n_end, w_end = count_bands(end)
    d_start, n_start, w_start = count_bands(start)

    day_raw = d_end - d_start
    night_raw = n_end - n_start
    weekend_raw = w_end - w_start

    def round_up_15(x: int) -> int:
        if x == 0:
            return 0
        return ((x + 14) // 15) * 15

    return {
        "day": round_up_15(day_raw),
        "night": round_up_15(night_raw),
        "weekend": round_up_15(weekend_raw),
    }
