def kin_distance(parents: dict, a: str, b: str):
    """Measure how two people in a family record are related."""

    def bfs_ancestors(person):
        """BFS upward through parents; returns {ancestor: shortest_distance}."""
        distances = {person: 0}
        queue = [person]
        i = 0
        while i < len(queue):
            node = queue[i]
            i += 1
            for p in parents.get(node, []):
                if p not in distances:
                    distances[p] = distances[node] + 1
                    queue.append(p)
        return distances

    anc_a = bfs_ancestors(a)
    anc_b = bfs_ancestors(b)

    best = None
    for c, da in anc_a.items():
        if c in anc_b:
            db = anc_b[c]
            if best is None:
                best = (da, db)
            elif da + db < best[0] + best[1]:
                best = (da, db)
            elif da + db == best[0] + best[1] and da < best[0]:
                best = (da, db)

    return best
