import re


def expand_slots(spec: str) -> list[str]:
    if not spec or spec.strip() == '':
        return []

    token_re = re.compile(r'^(!?)([A-Z][1-9][0-9]?)(-([A-Z][1-9][0-9]?))?$')

    result: list[str] = []

    for raw in spec.split(','):
        token = raw.strip()
        if token == '':
            raise ValueError("Empty token in spec")

        m = token_re.match(token)
        if not m:
            raise ValueError(f"Invalid token: {token!r}")

        is_removal = m.group(1) == '!'

        if m.group(3) is not None:
            # Range token
            start_slot = m.group(2)
            end_slot = m.group(4)
            if start_slot[0] != end_slot[0]:
                raise ValueError(f"Range endpoints must share the same letter: {token!r}")
            start_num = int(start_slot[1:])
            end_num = int(end_slot[1:])
            letter = start_slot[0]
            step = 1 if start_num <= end_num else -1
            slots = [f"{letter}{n}" for n in range(start_num, end_num + 1, step)]
        else:
            # Single slot token
            slots = [m.group(2)]

        if is_removal:
            for s in slots:
                if s in result:
                    result.remove(s)
        else:
            for s in slots:
                if s not in result:
                    result.append(s)

    return result
