def top_spenders(events: list[dict], k: int) -> list[tuple[str, int]]:
    # Sort by ts (stable sort preserves original order for equal ts)
    indexed_events = list(enumerate(events))
    indexed_events.sort(key=lambda x: x[1]["ts"])

    # orders: order_id -> [amount, customer, cancelled]
    orders: dict[str, dict] = {}
    customer_orders: dict[str, list[str]] = {}
    customer_first_buy_ts: dict[str, int] = {}

    for _, event in indexed_events:
        etype = event["type"]
        order_id = event["order"]
        ts = event["ts"]

        if etype == "buy":
            if order_id not in orders:
                customer = event["customer"]
                cents = event["cents"]
                orders[order_id] = {
                    "amount": cents,
                    "customer": customer,
                    "cancelled": False,
                }
                customer_orders.setdefault(customer, []).append(order_id)
                if customer not in customer_first_buy_ts or ts < customer_first_buy_ts[customer]:
                    customer_first_buy_ts[customer] = ts
            # else: ignore (order id already seen in a prior buy)

        elif etype == "refund":
            if order_id in orders and not orders[order_id]["cancelled"]:
                orders[order_id]["amount"] = max(0, orders[order_id]["amount"] - event["cents"])

        elif etype == "cancel":
            if order_id in orders:
                orders[order_id]["amount"] = 0
                orders[order_id]["cancelled"] = True

    # Compute totals per customer
    customer_totals: dict[str, int] = {}
    for customer, oid_list in customer_orders.items():
        total = sum(orders[oid]["amount"] for oid in oid_list)
        if total > 0:
            customer_totals[customer] = total

    # Rank: total desc, earliest accepted buy ts asc, name asc
    ranked = sorted(
        customer_totals.items(),
        key=lambda x: (-x[1], customer_first_buy_ts[x[0]], x[0]),
    )

    return [(name, total) for name, total in ranked[:k]]
