def parse_stanza(text: str) -> dict:
    result = {}
    current_section = None

    def _strip_comment(line: str) -> str:
        in_quotes = False
        for i, ch in enumerate(line):
            if ch == '"':
                in_quotes = not in_quotes
            elif ch == '#' and not in_quotes:
                return line[:i]
        return line

    def _convert_scalar(s: str) -> object:
        # optional '-' followed by one or more digits
        if s.startswith('-'):
            rest = s[1:]
            if rest and all(c in '0123456789' for c in rest):
                return int(s)
        else:
            if s and all(c in '0123456789' for c in s):
                return int(s)
        if s == 'yes':
            return True
        if s == 'no':
            return False
        return s

    def _convert_value(raw: str) -> object:
        # Rule a: quoted string
        if len(raw) >= 2 and raw[0] == '"' and raw[-1] == '"':
            return raw[1:-1]
        # Rule b: list
        if '|' in raw:
            parts = raw.split('|')
            return [_convert_scalar(p.strip()) for p in parts]
        # Rule c: scalar
        return _convert_scalar(raw)

    for line in text.split('\n'):
        # Step 1: remove comment
        line = _strip_comment(line)

        # Step 2: strip whitespace; skip empty lines
        line = line.strip()
        if not line:
            continue

        # Step 3: section header
        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1].strip()
            if not name:
                raise ValueError("Empty section name")
            if name not in result:
                result[name] = {}
            current_section = name
            continue

        # Step 4: entry
        if '=' not in line:
            raise ValueError("Entry must contain '='")
        key, _, raw_value = line.partition('=')
        key = key.strip()
        if not key:
            raise ValueError("Empty key")
        raw_value = raw_value.strip()

        # Step 5: default section
        if current_section is None:
            current_section = ""
            if "" not in result:
                result[""] = {}

        # Step 6: convert and store (later replaces earlier)
        result[current_section][key] = _convert_value(raw_value)

    # Remove empty "" section (shouldn't happen with our logic, but safe)
    if "" in result and not result[""]:
        del result[""]

    return result
