import re


def run_tally(program: str, max_steps: int) -> tuple[str, list[int]]:
    tokens = program.split()
    n = len(tokens)

    stack: list[int] = []
    output: list[int] = []
    pc = 0
    exec_count = 0

    int_re = re.compile(r'^-?\d+$')
    jmp_re = re.compile(r'^jmp:(-?\d+)$')
    jz_re = re.compile(r'^jz:(-?\d+)$')
    named_ops = {'dup', 'drop', 'swap', 'add', 'sub', 'mul', 'out'}

    while True:
        if pc == n:
            return ("done", output)
        if exec_count == max_steps:
            return ("limit", output)

        token = tokens[pc]
        exec_count += 1

        if int_re.match(token):
            stack.append(int(token))
            pc += 1

        elif token in named_ops:
            if token == 'dup':
                if len(stack) < 1:
                    return ("fault", output)
                stack.append(stack[-1])
                pc += 1
            elif token == 'drop':
                if len(stack) < 1:
                    return ("fault", output)
                stack.pop()
                pc += 1
            elif token == 'swap':
                if len(stack) < 2:
                    return ("fault", output)
                stack[-1], stack[-2] = stack[-2], stack[-1]
                pc += 1
            elif token == 'add':
                if len(stack) < 2:
                    return ("fault", output)
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
                pc += 1
            elif token == 'sub':
                if len(stack) < 2:
                    return ("fault", output)
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
                pc += 1
            elif token == 'mul':
                if len(stack) < 2:
                    return ("fault", output)
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
                pc += 1
            elif token == 'out':
                if len(stack) < 1:
                    return ("fault", output)
                val = stack.pop()
                output.append(val)
                pc += 1

        else:
            m = jmp_re.match(token)
            if m:
                k = int(m.group(1))
                new_pc = pc + k
                if new_pc < 0 or new_pc > n:
                    return ("fault", output)
                pc = new_pc
            else:
                m = jz_re.match(token)
                if m:
                    k = int(m.group(1))
                    if len(stack) < 1:
                        return ("fault", output)
                    val = stack.pop()
                    if val == 0:
                        new_pc = pc + k
                        if new_pc < 0 or new_pc > n:
                            return ("fault", output)
                        pc = new_pc
                    else:
                        pc += 1
                else:
                    return ("fault", output)
