def plan_rounds(deps: dict, capacity: int) -> list[list[str]]:
    if capacity < 1:
        raise ValueError("capacity must be at least 1")

    for task, prereqs in deps.items():
        for p in prereqs:
            if p not in deps:
                raise ValueError(f"Unknown prerequisite: {p!r}")

    if not deps:
        return []

    # Precompute number of direct dependents (fixed)
    dependents_count = {task: 0 for task in deps}
    for task, prereqs in deps.items():
        for p in prereqs:
            dependents_count[p] += 1

    done = set()
    rounds = []

    while len(done) < len(deps):
        ready = [
            task for task in deps
            if task not in done and all(p in done for p in deps[task])
        ]

        if not ready:
            raise ValueError("Dependency cycle detected")

        ready.sort(key=lambda t: (-dependents_count[t], t))

        round_tasks = ready[:capacity]
        rounds.append(round_tasks)
        done.update(round_tasks)

    return rounds
